From 67caad3e55c201597bfdb59f209c658ce9b74f90 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:47:48 +0100
Subject: [PATCH] kcms/connections: bring up ports when a bond, bridge or team
 connects

Ports created in the editor don't autoconnect, and every save reset the
connection's autoconnect-slaves, so connecting a bridge left it stuck. New
bond, bridge and team connections now set it, and edits keep its value.

BUG: 421867
---
 kcms/kcm_connections/kcm.cpp              | 4 ++++
 kcms/kcm_connections_qml/kcm.cpp          | 5 +++++
 libs/editor/settings/connectionwidget.cpp | 2 ++
 libs/editor/settings/connectionwidget.h   | 1 +
 4 files changed, 12 insertions(+)

diff --git a/kcms/kcm_connections/kcm.cpp b/kcms/kcm_connections/kcm.cpp
index 3a02834f4..c20ed6796 100644
--- a/kcms/kcm_connections/kcm.cpp
+++ b/kcms/kcm_connections/kcm.cpp
@@ -440,6 +440,10 @@ void KCMNetworkmanagement::onRequestCreateConnection(int connectionType, const Q
                 connectionSettings->setAutoconnect(false);
             }
         }
+        if (type == NetworkManager::ConnectionSettings::Bond || type == NetworkManager::ConnectionSettings::Bridge
+            || type == NetworkManager::ConnectionSettings::Team) {
+            connectionSettings->setAutoconnectSlaves(NetworkManager::ConnectionSettings::ConnectAllSlaves);
+        }
         if (type == NetworkManager::ConnectionSettings::WireGuard) {
             NetworkManager::WireGuardSetting::Ptr wireguardSetting =
                 connectionSettings->setting(NetworkManager::Setting::WireGuard).dynamicCast<NetworkManager::WireGuardSetting>();
diff --git a/kcms/kcm_connections_qml/kcm.cpp b/kcms/kcm_connections_qml/kcm.cpp
index efe5e0c83..fa4a439c1 100644
--- a/kcms/kcm_connections_qml/kcm.cpp
+++ b/kcms/kcm_connections_qml/kcm.cpp
@@ -1070,6 +1070,11 @@ void KCMNetworkManagementQml::onRequestCreateConnection(int connectionType, cons
         connectionSettings->setAutoconnect(false);
     }

+    if (type == NetworkManager::ConnectionSettings::Bond || type == NetworkManager::ConnectionSettings::Bridge
+        || type == NetworkManager::ConnectionSettings::Team) {
+        connectionSettings->setAutoconnectSlaves(NetworkManager::ConnectionSettings::ConnectAllSlaves);
+    }
+
     if (type == NetworkManager::ConnectionSettings::WireGuard) {
         auto ipv4Setting = connectionSettings->setting(NetworkManager::Setting::Ipv4).dynamicCast<NetworkManager::Ipv4Setting>();
         auto ipv6Setting = connectionSettings->setting(NetworkManager::Setting::Ipv6).dynamicCast<NetworkManager::Ipv6Setting>();
diff --git a/libs/editor/settings/connectionwidget.cpp b/libs/editor/settings/connectionwidget.cpp
index 5b224d0dd..20244da8e 100644
--- a/libs/editor/settings/connectionwidget.cpp
+++ b/libs/editor/settings/connectionwidget.cpp
@@ -25,6 +25,7 @@ ConnectionWidget::ConnectionWidget(const NetworkManager::ConnectionSettings::Ptr
     , m_type(settings->connectionType())
     , m_masterUuid(settings->master())
     , m_slaveType(settings->slaveType())
+    , m_autoconnectSlaves(settings->autoconnectSlaves())
 {
     m_widget->setupUi(this);

@@ -113,6 +114,7 @@ NMVariantMapMap ConnectionWidget::setting() const
     settings.setAutoconnect(m_widget->autoconnect->isChecked());
     settings.setMaster(m_masterUuid);
     settings.setSlaveType(m_slaveType);
+    settings.setAutoconnectSlaves(m_autoconnectSlaves);

     if (m_widget->allUsers->isChecked()) {
         settings.setPermissions(QHash<QString, QString>());
diff --git a/libs/editor/settings/connectionwidget.h b/libs/editor/settings/connectionwidget.h
index 97b4324fe..c499b2eda 100644
--- a/libs/editor/settings/connectionwidget.h
+++ b/libs/editor/settings/connectionwidget.h
@@ -52,6 +52,7 @@ private:
     NetworkManager::ConnectionSettings::ConnectionType m_type;
     QString m_masterUuid;
     QString m_slaveType;
+    NetworkManager::ConnectionSettings::AutoconnectSlaves m_autoconnectSlaves;
 };

 #endif // PLASMA_NM_CONNECTION_WIDGET_H
